import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as n,c as e,o as h,ag as i,G as d}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cindy 上手：把 Claude Code、Codex、Pi 装进同一个工作区","description":"Cindy 是开源的桌面加手机 AI 智能体应用。它把 Claude Code、Codex、Pi 三个 agent 引擎放进同一个界面，让任务、记忆和技能跟着你跨电脑、跨手机走。本页带你装上它、10 分钟跑通第一个任务，并分清哪些数据留在本机、哪些会发出去。","frontmatter":{"title":"Cindy 上手：把 Claude Code、Codex、Pi 装进同一个工作区","description":"Cindy 是开源的桌面加手机 AI 智能体应用。它把 Claude Code、Codex、Pi 三个 agent 引擎放进同一个界面，让任务、记忆和技能跟着你跨电脑、跨手机走。本页带你装上它、10 分钟跑通第一个任务，并分清哪些数据留在本机、哪些会发出去。","domain":"product","tags":["multi-agent","coding-agent","device-link","open-source"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/cindy/cindy.md","filePath":"zh/products/cindy/cindy.md","lastUpdated":1795792629000}'),l={name:"zh/products/cindy/cindy.md"};function r(k,s,p,o,g,E){const t=n("DocDiagram");return h(),e("div",null,[s[0]||(s[0]=i("",31)),d(t,{src:"/diagrams/cindy-architecture.svg",alt:"这张分层架构图回答两个问题：一句任务从手机或电脑发出后，经过哪几层才到达 agent 引擎；哪些数据始终留在你的电脑上，哪些会发到 Cindy 的服务或模型供应商。图里有四个区域。左边是你的设备：手机和电脑 B。手机只当遥控器，本地不运行 agent，只经 Cindy 云端的 Device Link 中转连到电脑 A，调用白名单内的通道。电脑 B 既可以当控制端，也可以当被控端。中间是电脑 A 上的 Cindy 客户端，从上到下四层：界面，也就是 Renderer，只向主进程提交意图；主进程，也就是 Main，里面有输入协调器、本地 SQLite 数据库、自动化调度和聊天渠道；会话层，也就是 maker-core，由 Maker 与 Session 把三种 harness 的输出统一成同一种事件流，再回到界面；最下面是 harness 适配层，对应 Claude Code、Codex、Pi 和插件引擎。适配层之下是 harness 子进程，它读写电脑 A 上的文件、浏览器和应用；项目文件留在执行任务的那台电脑。右侧下方是模型供应商，有四类：已有订阅、API key、本地模型和 Cindy 官方模型服务。harness 的模型请求先经过本机回环代理与协议桥接，再由电脑 A 直接发往所选的供应商；只有选官方模型服务时，请求才会经过云端的网关。上方是 Cindy 云端，与本机有关的只有四条连线：第一，设备信息与在线心跳，由电脑发往云端，仅登录模式；第二，使用统计发往 TapDB，默认开，可以关；第三，云伙伴的对话层同步，是双向的；第四，选择官方模型服务时的模型请求。本地模式，也就是跳过登录时，没有心跳，没有使用统计上报，也没有 Device Link。Agent-Net 是 Beta 功能，默认关，画成 Device Link 中转旁的一条可选加密路径。本图省略了服务端的内部模块，因为后端不在开源仓库里；不对官方中继是否会读取数据下结论；不标价格与额度。",width:1080}),s[1]||(s[1]=i("",118))])}const u=a(l,[["render",r]]);export{b as __pageData,u as default};
